	/**
	 * Start a server instance on the specified port.
	 * This server must be disposed before attempting to create another.
	 * @param dirPath server root directory
	 * @param port RMI registry port, 0 indicates that default port should be used
	 * @param authMode authentication mode (-1 for no authentication)
	 * @param enableAltLoginName if true enable alternate login name
	 * @param enableSSHAuthentication if true SSH authentication will be enabled
	 * @param enableAnonymousAuthentication if true anonymous usage is allowed
	 * @throws IOException
	 */
	public static void startServer(string dirPath, int port, int authMode,
			bool enableAltLoginName, bool enableSSHAuthentication,
			bool enableAnonymousAuthentication)
    {

		// Set client-side compression to match server
		DataBuffer.enableCompressedSerializationOutput(enableCompressionOnServerStart);

		if (port == 0) {
			port = GHIDRA_TEST_SERVER_PORT;
		}

		Msg.debug(typeof(ServerTestUtil), "--- Preparing to start Ghidra Server ---");
		Msg.debug(typeof(ServerTestUtil),
			"     Authentication: " + (authMode < 0 ? "None" : AUTH_MODES[authMode]));
		Msg.debug(typeof(ServerTestUtil), "     Enable Alternate Login Name: " + enableAltLoginName);
		Msg.debug(typeof(ServerTestUtil),
			"     Enable Anonymous Login: " + enableAnonymousAuthentication);

		// Force client-side use of newly generated CA certificates
		System.setProperty(DefaultTrustManagerFactory.GHIDRA_CACERTS_PATH_PROPERTY,
			getTestPkiCACertsPath());
		DefaultSSLContextInitializer.initialize(true);

		string javaCommand =
			System.getProperty("java.home") + File.separator + "bin" + File.separator + "java";

		List<string> argList = new();
		argList.add("-cp");
		argList.add("\"" + System.getProperty("java.class.path").replace("\\", "/") + "\"");

		argList.add("-Xmx512M");

		argList.add("-Ddb.buffers.DataBuffer.compressedOutput=" + enableCompressionOnServerStart);
		argList.add("-D" + DefaultTrustManagerFactory.GHIDRA_CACERTS_PATH_PROPERTY + "=" +
			getTestPkiCACertsPath());
		argList.add("-D" + DefaultKeyManagerFactory.KEYSTORE_PATH_PROPERTY + "=" +
			getTestPkiServerKeystorePath());
		argList.add("-D" + DefaultKeyManagerFactory.KEYSTORE_PASSWORD_PROPERTY + "=" +
			TEST_PKI_SERVER_PASSPHRASE);
		argList.add("-Xrunjdwp:transport=dt_socket,server=y,suspend=n,address=*:18202"); // *: for remote debug support
		argList.add("-DSystemUtilities.isTesting=true");

		// -Djava.security.policy=C:/policy
//		URL policy = ResourceManager.getResource("policy");
//		if (policy == null) {
//			throw new RuntimeException("Failed to find security policy resource");
//		}
//		argList.add("-Djava.security.policy=" + policy.toExternalForm());

		argList.add("ghidra.server.remote.GhidraServer");
		if (authMode >= 0) {
			argList.add("-a" + authMode);
		}
		if (enableAltLoginName) {
			argList.add("-u");
		}
		if (enableSSHAuthentication) {
			argList.add("-ssh");
		}
		if (enableAnonymousAuthentication) {
			argList.add("-anonymous");
		}

		// Force use of localhost interface only
		argList.add("-ip" + LOCALHOST);
		argList.add("-i" + LOCALHOST);

		argList.add("-p" + port);
		argList.add(dirPath);


		try {
			// Command line argument is too long on Windows, so use an @arg-file
			argsFile =
				Files.createTempFile(Application.getUserTempDirectory().toPath(), "args", ".txt");
			Files.write(argsFile, argList);
			Console.WriteLine(javaCommand + " \"@" + argsFile + "\"");

			serverProcess = new ProcessBuilder(javaCommand, "@" + argsFile).start();
			serverRepositories = dirPath;

			cmdOut = new IOThread(serverProcess.getInputStream());
			cmdErr = new IOThread(serverProcess.getErrorStream());
			cmdOut.start();
			cmdErr.start();
		}
		catch (Exception e) {
			e.printStackTrace();
			throw new AssertException("Exception starting Ghidra Server", e);
		}

		Msg.info(typeof(ServerTestUtil), "Waiting for Ghidra Server RMI registration to complete...");
		cmdOut.waitForServerStartOrTermination(); // based upon message output only
		if (!cmdOut.serverStartComplete) {
			throw new AssertException("Ghidra Server failed to start");
		}

		waitUntilServerAvailable(GHIDRA_TEST_SERVER_PORT);
	}

	private static void waitUntilServerAvailable(int basePort)
    {

		RMIServerPortFactory portFactory = new RMIServerPortFactory(basePort);

		int maxTries = SERVER_STARTUP_MAXWAIT_MS / 200;
		int tries = 0;
		bool success = false;
		try {
			while (tries++ < maxTries) {
				Thread.sleep(200);
				if (isServerRegistered(portFactory.getRMIRegistryPort()) &&
					canConnect(portFactory.getRMISSLPort())) {
					success = true;
					return;
				}
			}
		}
		catch (InterruptedException e) {
			// ignore - stop waiting
		}
		finally {
			if (!success) {
				disposeServer();
			}
		}

		throw new IOException("Timed-out waiting for Ghidra Server to start");
	}

	private static bool isServerRegistered(int port)
    {
		Registry reg = LocateRegistry.getRegistry(LOCALHOST, port, new SslRMIClientSocketFactory());
		try {
			reg.lookup(GhidraServerHandle.BIND_NAME);
			return true;
		}
		catch (Exception ce) {
			return false;
		}
	}

	private static bool canConnect(int port) {

		Socket socket = null;
		try {
			SocketAddress sockaddr = new InetSocketAddress(LOCALHOST, port);
			socket = new Socket();
			socket.connect(sockaddr, 500);
			return true;
		}
		catch (UnknownHostException e) {
			return true; // defer error
		}
		catch (IOException e) {
			return false; // connect error?
		}
		finally {
			if (socket != null) {
				try {
					socket.close();
				}
				catch (IOException e) {
					// ignore
				}
			}
		}
	}

	/**
	 * Start new server instance and return server adapter.
	 * This method blocks until server is started and adapter is connected.  
	 * @param serverRoot root directory
	 * @param users list of server users
	 * @return server adapter
	 * @throws IOException if there are any IOExceptions starting the server
	 */
	public static RepositoryServerAdapter getServerAdapter(File serverRoot, string[] users)
    {

		RepositoryServerAdapter rsa = null;

		bool success = false;
		try {

			createServer(serverRoot.getAbsolutePath(), GHIDRA_TEST_SERVER_PORT, users);

			waitUntilServerAvailable(GHIDRA_TEST_SERVER_PORT);

			rsa = ClientUtil.getRepositoryServer(LOCALHOST, GHIDRA_TEST_SERVER_PORT);
			rsa.connect();
			success = true;
		}
		catch (NotConnectedException e) {
			// note: this will trigger a popup dialog
		}
		finally {
			if (!success) {
				disposeServer();
			}
		}

		return rsa;
	}

	public static void disposeServer() {

		System.clearProperty(DefaultTrustManagerFactory.GHIDRA_CACERTS_PATH_PROPERTY);

		TransientProjectManager.getTransientProjectManager().dispose();

		// restore default compression: enabled
		DataBuffer.enableCompressedSerializationOutput(
			Boolean.parseBoolean(
				System.getProperty(DataBuffer.COMPRESSED_SERIAL_OUTPUT_PROPERTY,
					"true")));

		if (serverProcess != null) {

			cmdOut.dispose();
			cmdErr.dispose();

			Msg.debug(typeof(ServerTestUtil), "*** Terminating Ghidra Server Instance... ***");

			serverProcess.destroy();

			Msg.debug(typeof(ServerTestUtil), "\tafter call to destroy");

			try {
				serverProcess.waitFor();
			}
			catch (InterruptedException e) {
				// don't care
			}

			if (serverProcess.isAlive()) {
				Msg.debug(typeof(ServerTestUtil), "Its alive...");
			}

			dumpServerLog();

			serverProcess = null;
			serverRepositories = null;

			if (testPkiDirectory != null) {
				try {
					FileUtils.deleteDirectory(testPkiDirectory);
				}
				catch (IOException e) {
					// Will likely be an error the next time the test starts
					e.printStackTrace();
				}
				finally {
					testPkiDirectory = null;
				}
			}
		}
		if (argsFile != null && Files.exists(argsFile)) {
			try {
				Files.delete(argsFile);
			}
			catch (IOException e) {
				// don't care
			}
		}
	}

	private static void dumpServerLog() {

		File serverLogFile = new File(serverRepositories, "server.log");
		if (!serverLogFile.exists()) {
			Msg.error(typeof(ServerTestUtil), "Ghidra Server log not found: " + serverLogFile);
			return;
		}

		Msg.debug(typeof(ServerTestUtil), ">>> START Ghidra Server Log Dump >>>");

		try
{
    using (BufferedReader r = new BufferedReader(new FileReader(serverLogFile)))
    {

			string s;
			while ((s = r.readLine()) != null) {
				Console.WriteLine("    SERVER: " + s);
			}
		
    }
}
		catch (IOException e) {
			Msg.error(typeof(ServerTestUtil), "Error dumping file: " + serverLogFile, e);
		}

		Msg.debug(typeof(ServerTestUtil), "<<< END Ghidra Server Log Dump <<<");
	}

	/**
	 * Create KnownUsers file containing the specified list of users.
	 * @param dirPath server root directory
	 * @param userNames list of user names
	 * @throws IOException if there are any exceptions creating users
	 */
	public static void createUsers(string dirPath, params string[] userNames)
    {

		File rootDir = new File(dirPath);
		File userFile = new File(rootDir, UserManager.USER_PASSWORD_FILE);

		string[] entries = new string[userNames.length];
		for (int i = 0; i < userNames.length; i++) {
			char[] hash = HashUtilities.getSaltedHash(HashUtilities.SHA256_ALGORITHM,
				"changeme".toCharArray());
			entries[i] = userNames[i] + ":" + (new string(hash)) + ":*";
		}

		writeFile(userFile, entries);
	}

	private static void writeFile(File file, params string[] lines)
    {

		file.delete();

		BufferedWriter bw = new BufferedWriter(new FileWriter(file));
		try {
			foreach (string line in lines) {
				bw.write(line);
				bw.newLine();
			}
		}
		finally {
			try {
				bw.close();
			}
			catch (IOException e) {
				// we tried
			}
		}
	}

	private static void addSSHKeys(string dirPath, string privateKey, string privateKeyFilename,
			string publicKey, string publicKeyFilename)
    {

		File rootDir = new File(dirPath);
		File sshDir = new File(rootDir, "~ssh");
		FileUtilities.mkdirs(sshDir);

		FileUtilities.writeStringToFile(new File(sshDir, privateKeyFilename), privateKey);
		FileUtilities.writeStringToFile(new File(sshDir, publicKeyFilename), publicKey);
	}

	/**
	 * Creates a versioned server repository filesystem prior to starting a Ghidra Server.
	 * The following test user permissions are granted:
	 * <pre>
	 * 	test=ADMIN
	 *  userA=READ_ONLY
	 *  userB=WRITE
	 * </pre>
	 * @param dirPath the location for the server to be created
	 * @param repoName the name of the repository
	 * @param userAccessLines the permissions for the set of users being created (see above)
	 * @return newly created versioned filesystem (caller is responsible for invoking the
	 * dispose method on the returned object.
	 * @throws IOException 
	 */
	private static LocalFileSystem createRepository(string dirPath, string repoName,
			params string[] userAccessLines)
    {

		File repoDir = new File(dirPath, NamingUtilities.mangle(repoName));
		FileUtilities.mkdirs(repoDir);

		LocalFileSystem repoFileSystem =
			LocalFileSystem.getLocalFileSystem(repoDir.getAbsolutePath(), true, true, false, false);

		File userAccessFile = new File(repoDir, "userAccess.acl");
		writeFile(userAccessFile, userAccessLines);

		return repoFileSystem;
	}

	private static void createRepositoryItem(LocalFileSystem repoFilesystem, string name,
			string folderPath, int numFunctions)
    {

		ToyProgramBuilder builder = new ToyProgramBuilder(name, true);

		try {
			Program program = builder.getProgram();

			int funcAddr = 0;
			for (int i = 0; i < numFunctions; i++) {
				string funcAddrStr = string.valueOf(funcAddr);
				builder.createMemory("func" + i, funcAddrStr, 2);
				builder.addBytesReturn(funcAddrStr);
				builder.disassemble(funcAddrStr, 2);
				builder.createFunction(funcAddrStr);
				funcAddr += 2;
			}

			setProgramHashes(program);

			createRepositoryItem(repoFilesystem, name, folderPath, program);
		}
		catch (CancelledException e) {
			throw new RuntimeException(e); // unexpected
		}
		catch (InvalidNameException e) {
			throw new IOException(e);
		}
		finally {
			builder.dispose();
		}
	}

	public static void createRepositoryItem(LocalFileSystem repoFilesystem, string name,
			string folderPath, Program program)
    {

		ContentHandler<object> contentHandler = DomainObjectAdapter.getContentHandler(program);
		long checkoutId = contentHandler.createFile(repoFilesystem, null, folderPath, name, program,
			TaskMonitor.DUMMY);
		LocalFolderItem item = repoFilesystem.getItem(folderPath, name);
		if (item == null) {
			throw new IOException("Item not found: " + FileSystem.SEPARATOR + name);
		}
		item.terminateCheckout(checkoutId, false);
	}

	/**
	 * Create and populate server test repositories "Test" and "Test1".  The ADMIN_USER "test" 
	 * is added by default to both repositories. 
	 * @param dirPath server root
	 * @throws Exception
	 */
	public static void createPopulatedTestServer(string dirPath)
    {

		Msg.info(typeof(ServerTestUtil), "Constructing Ghidra Server for testing: " + dirPath);

		File rootDir = new File(dirPath);
		FileUtilities.deleteDir(rootDir);
		FileUtilities.mkdirs(rootDir);

		createUsers(dirPath, new string[] { ADMIN_USER });

		string[] keys = SSHKeyUtil.generateSSHRSAKeys();
		addSSHKeys(dirPath, keys[0], "test.key", keys[1], "test.pub");

		LocalFileSystem repoFilesystem = createRepository(dirPath, "Test", ADMIN_USER + "=ADMIN");
		try {
			createRepositoryItem(repoFilesystem, "foo", "/", 0);
			createRepositoryItem(repoFilesystem, "notepad", "/", 0);
			createRepositoryItem(repoFilesystem, "bash", "/f1", 0);
		}
		finally {
			repoFilesystem.dispose();
		}

		repoFilesystem = createRepository(dirPath, "Test1", "=ANONYMOUS_ALLOWED",
			ADMIN_USER + "=ADMIN");
		try {
			createRepositoryItem(repoFilesystem, "foo1", "/", 0);
			createRepositoryItem(repoFilesystem, "notepad1", "/", 0);
			createRepositoryItem(repoFilesystem, "bash1", "/f2", 0);
			createRepositoryItem(repoFilesystem, "foo2", "/", 2);
		}
		finally {
			repoFilesystem.dispose();
		}
	}

	/**
	 * Create and populate server test repositories "Test" and "Test1".  The ADMIN_USER "test" 
	 * is added by default to both repositories. 
	 * @param dirPath server root
	 * @param repoName repository name
	 * @param contentProvider repository content provider callback 
	 * (use {@link #createRepositoryItem(LocalFileSystem, String, String, Program)} to add content.
	 * @throws Exception
	 */
	public static void createPopulatedTestServer(string dirPath, string repoName,
			Consumer<LocalFileSystem> contentProvider)
    {

		Msg.info(typeof(ServerTestUtil), "Constructing Ghidra Server for testing: " + dirPath);

		File rootDir = new File(dirPath);
		FileUtilities.deleteDir(rootDir);
		FileUtilities.mkdirs(rootDir);

		createUsers(dirPath, new string[] { ADMIN_USER });

		string[] keys = SSHKeyUtil.generateSSHRSAKeys();
		addSSHKeys(dirPath, keys[0], "test.key", keys[1], "test.pub");

		LocalFileSystem repoFilesystem = createRepository(dirPath, repoName, ADMIN_USER + "=ADMIN");
		try {
			contentProvider.accept(repoFilesystem);
		}
		finally {
			repoFilesystem.dispose();
		}
	}

	/**
	 * Sets dummy hash values for the given program.
	 *
	 * @param program the current program
	 */
	private static void setProgramHashes(Program program) {
		int id = program.startTransaction("sethashes");
		try {
			string md5 = RandomStringUtils.randomNumeric(32);
			program.setExecutableMD5(md5);
			string sha256 = RandomStringUtils.randomNumeric(64);
			program.setExecutableSHA256(sha256);
		}
		finally {
			program.endTransaction(id, true);
		}
	}

	/**
	 * Generate self-signed test-CA key/certificate and a test user key/certificate
	 */
	private static void generatePkiCerts()
    {

		string caPath = getTestPkiCACertsPath(); // CA certs keystore is .jks file
		File caFile = new File(caPath);
		if (caFile.exists() && !caFile.delete()) {
			throw new RuntimeException("Failed to generate new test-CA key file: " + caPath);
		}

		string userKeystorePath = getTestPkiUserKeystorePath(); // user keystore is .p12 file
		File userKeystoreFile = new File(userKeystorePath);
		if (userKeystoreFile.exists() && !userKeystoreFile.delete()) {
			throw new RuntimeException(
				"Failed to generate new test-user key file: " + userKeystorePath);
		}

		string serverKeystorePath = getTestPkiServerKeystorePath(); // server keystore is .p12 file
		File serverKeystoreFile = new File(serverKeystorePath);
		if (serverKeystoreFile.exists() && !serverKeystoreFile.delete()) {
			throw new RuntimeException(
				"Failed to generate new test-server key file: " + serverKeystorePath);
		}

		// Generate CA certificate and keystore
		Msg.info(typeof(ServerTestUtil), "Generating self-signed CA cert: " + caPath);
		PrivateKeyEntry caEntry = PKITestUtils.createKeyEntry("test-CA", TEST_PKI_CA_DN,
			TEST_PKI_CERT_DURATIONS_DAYS, null, true, null, "PKCS12", null,
			DefaultKeyManagerFactory.DEFAULT_PASSWORD.toCharArray());
		PKIUtils.exportX509Certificates(caEntry.getCertificateChain(), caFile);

		// Generate User/Client certificate and keystore
		Msg.info(typeof(ServerTestUtil), "Generating test user key/cert (signed by test-CA, pwd: " +
			TEST_PKI_USER_PASSPHRASE + "): " + userKeystorePath);
		PKITestUtils.createKeyEntry("test-sig", TEST_PKI_USER_DN, TEST_PKI_CERT_DURATIONS_DAYS,
			caEntry, false, userKeystoreFile, "PKCS12", null,
			TEST_PKI_USER_PASSPHRASE.toCharArray());

		// Generate Server certificate and keystore - intended for localhost testing only
		Msg.info(typeof(ServerTestUtil), "Generating test server key/cert (signed by test-CA, pwd: " +
			TEST_PKI_SERVER_PASSPHRASE + "): " + serverKeystorePath);
		PKITestUtils.createKeyEntry("test-sig", TEST_PKI_SERVER_DN, TEST_PKI_CERT_DURATIONS_DAYS,
			caEntry, false, serverKeystoreFile, "PKCS12", getLocalHostAlternateNames(),
			TEST_PKI_SERVER_PASSPHRASE.toCharArray());
	}
	
	private static Set<string> getLocalHostAlternateNames()
    {
		// Collect alternate IPv4 hostnames and addresses for inclusion in certificate
		Set<string> altNames = new();
		Enumeration<NetworkInterface> nets = NetworkInterface.getNetworkInterfaces();
		while (nets.hasMoreElements()) {
			NetworkInterface netint = nets.nextElement();
			Enumeration<InetAddress> addrs = netint.getInetAddresses();
			while (addrs.hasMoreElements()) {
				InetAddress addr = addrs.nextElement();
				if (addr is Inet4Address) {
					altNames.add(addr.getHostAddress());
					altNames.add(addr.getHostName());
					altNames.add(addr.getCanonicalHostName());
				}
			}
		}
		return altNames;
	}

	/**
	 * Add a new user to an existing local Ghidra Test Server using the ServerAdmin class. 
	 * @param serverRoot server's repositories root directory
	 * @param name user name
	 * @param dn DN or null (applies to PKI authentication only)
	 * @throws Exception
	 */
	public static void addUser(File serverRoot, string name, string dn)
    {
		ServerAdmin serverAdmin = new ServerAdmin();
		if (dn != null) {
			serverAdmin.execute(new string[] { serverRoot.getAbsolutePath(), "-dn", name, dn });
		}
		else {
			serverAdmin.execute(new string[] { serverRoot.getAbsolutePath(), "-add", name });
		}
	}

	/**
	 * Grant an existing user access to a repository for an existing local Ghidra Test Server 
	 * using the ServerAdmin class. 
	 * @param serverRoot server's repositories root directory
	 * @param name user name
	 * @param repoName existing repository name
	 * @param access an access string: "+r", "+w", "+a"
	 * @throws Exception
	 */
	public static void setUserAccess(File serverRoot, string name, string repoName, string access)
    {
		ServerAdmin serverAdmin = new ServerAdmin();
		serverAdmin.execute(
			new string[] { serverRoot.getAbsolutePath(), "-grant", name, access, repoName });
	}
	
	/**
	 * Add PKI user to server
	 * @param serverRoot
	 * @param userName
	 * @param dn
	 * @throws Exception
	 */
	public static void addPKIUser(File serverRoot, string userName, string dn)
    {
		ServerAdmin serverAdmin = new ServerAdmin();
		if (dn != null) {
			serverAdmin.execute(new string[] { serverRoot.getAbsolutePath(), "-dn", userName, dn });
		}
		else {
			serverAdmin.execute(new string[] { serverRoot.getAbsolutePath(), "-add", userName });
		}
	}
	
